def secucode(code):
    if code.startswith(('6','9','5')): return f'{code}.SH'
    if code.startswith(('8','4')):     return f'{code}.BJ'
    return f'{code}.SZ'
def secid(code):
    return ('1.' if code.startswith(('6','9','5')) else '0.') + code

