import numpy as np
def kline_similarity(a,b):
    return float(np.mean([np.corrcoef(a[:,i],b[:,i])[0,1] for i in range(4)]))
def find_similar(hist, query, topn=20, win=60):
    scores=[(kline_similarity(hist[i:i+win],query), i) for i in range(len(hist)-win-10)]
    scores.sort(reverse=True)
    return scores[:topn]

import numpy as np
def cos(a,b):
    return float(a@b/(np.linalg.norm(a)*np.linalg.norm(b)+1e-12))
def similar_kline(close, win=20, topk=5, fwd=5):
    q=close[-win:]/close[-win]
    best=[]
    for i in range(len(close)-win-fwd):
        seg=close[i:i+win]/close[i]
        best.append((cos(q,seg), i+win))
    best.sort(reverse=True)
    fwd_rets=[(close[j+fwd]/close[j]-1) for _,j in best[:topk]]
    return {'mean':float(np.mean(fwd_rets)), 'win_rate':float(np.mean([r>0 for r in fwd_rets]))}

def dtw(x,y):
    n,m=len(x),len(y); D=np.full((n+1,m+1),np.inf); D[0,0]=0
    for i in range(1,n+1):
        for j in range(1,m+1):
            D[i,j]=abs(x[i-1]-y[j-1])+min(D[i-1,j],D[i,j-1],D[i-1,j-1])
    return D[n,m]

